#[cfg(test)]
mod tests {
    use crate::graph::{param_meta, ALL_NODE_KINDS};

    /// Every kind and every parameter with a (non-empty) English
    /// tooltip has its Russian line. This is what turns the runtime's
    /// English fallback from a rot vector into a bridge for the moment
    /// between adding a parameter and translating it.
    #[test]
    fn ru_corpus_is_complete() {
        let mut missing = Vec::new();
        for kind in ALL_NODE_KINDS {
            let s = kind.schema();
            if super::node_help_ru(s.id).is_none() {
                missing.push(format!("{} (help)", s.id));
            }
            // The empty-body note is prose on screen like any hover,
            // so it belongs to the same rule: a kind that grows one
            // and has no Russian line fails here rather than showing
            // an English sentence in a Russian UI forever.
            // Each option's own note, the same rule.
            for (key, value) in (s.params)() {
                if let crate::value::Value::Enum(names, _) = value {
                    for i in 0..names.len() {
                        if crate::graph::param_option_note(*kind, key, i).is_some()
                            && super::param_option_note_ru(s.id, key, i).is_none()
                        {
                            missing.push(format!("{}.{} option {} (note)", s.id, key, names[i]));
                        }
                    }
                }
            }
            if crate::graph::no_params_note(*kind).is_some()
                && super::no_params_note_ru(s.id).is_none()
            {
                missing.push(format!("{} (no-params note)", s.id));
            }
            for (key, _) in (s.params)() {
                let Some(meta) = param_meta(*kind, key) else {
                    continue;
                };
                if meta.tooltip.is_empty() {
                    continue;
                }
                if super::param_tooltip_ru(s.id, key).is_none() {
                    missing.push(format!("{}.{}", s.id, key));
                }
            }
        }
        assert!(
            missing.is_empty(),
            "params without a Russian tooltip (add them to graph_ru.rs):\n{}",
            missing.join("\n")
        );
    }
}
